"""Parse and index inclusive holiday dates and ranges."""

import datetime as dt
import re
from bisect import bisect_right

from .errors import PlanError, describe_value
from .rules import DATE

HOLIDAY = re.compile(rf"({DATE})(?:\.\.({DATE}))?")


class Holidays:
    def __init__(self, blocks):
        self.blocks = tuple(blocks)
        self.ends = tuple(block.stop for block in self.blocks)

    def __bool__(self):
        return bool(self.blocks)

    def containing(self, ordinal):
        index = bisect_right(self.ends, ordinal)
        if index < len(self.blocks) and self.blocks[index].start <= ordinal:
            return self.blocks[index]
        return None

    def overlapping(self, first, last):
        """Yield full holiday blocks intersecting the inclusive ordinal range."""
        for index in range(bisect_right(self.ends, first), len(self.blocks)):
            block = self.blocks[index]
            if block.start > last:
                return
            yield block


def load_holidays(raw):
    if not isinstance(raw, list):
        raise PlanError("holidays must be a list")
    ranges = []
    for entry in raw:
        match = HOLIDAY.fullmatch(entry) if isinstance(entry, str) else None
        try:
            if match is None:
                raise ValueError
            start = dt.date.fromisoformat(match[1]).toordinal()
            end = dt.date.fromisoformat(match[2]).toordinal() if match[2] else start
            if end < start:
                raise ValueError
        except ValueError as exc:
            raise PlanError(f"invalid holiday {describe_value(entry)}") from exc
        ranges.append((start, end + 1))

    blocks = []
    for start, stop in sorted(ranges):
        if blocks and start <= blocks[-1].stop:
            blocks[-1] = range(blocks[-1].start, max(stop, blocks[-1].stop))
        else:
            blocks.append(range(start, stop))
    return Holidays(blocks)
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd

from .rules import ELAPSED_MINUTES

DAY_SECONDS = 24 * 60 * 60
LAST_ORDINAL = dt.date.max.toordinal()
CALENDAR_END = LAST_ORDINAL * DAY_SECONDS
GREGORIAN_CYCLE_MONTHS = 400 * 12


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # seconds on the UTC timeline, relative to 0001-01-01
    end: int


def as_instant(value):
    wall = (value.toordinal() - 1) * DAY_SECONDS
    wall += value.hour * 3600 + value.minute * 60 + value.second
    offset = value.utcoffset()
    return wall - (offset.days * DAY_SECONDS + offset.seconds)


def local_instant(value, zone):
    # fold=0 uses the earlier instant in a fold and the pre-gap offset in a gap.
    return as_instant(value.replace(tzinfo=zone, fold=0))


def date_at(seconds):
    ordinal = seconds // DAY_SECONDS + 1
    return dt.date.fromordinal(max(1, min(ordinal, LAST_ORDINAL)))


def _utc_datetime(seconds):
    return dt.datetime.min + dt.timedelta(seconds=seconds)


def _to_local(utc, zone):
    return zone.fromutc(utc.replace(tzinfo=zone))


def _boundary_probe(seconds):
    return min(max(seconds, DAY_SECONDS), CALENDAR_END - DAY_SECONDS - 1)


def _local_ordinal(seconds, zone):
    try:
        return _to_local(_utc_datetime(seconds), zone).toordinal()
    except OverflowError:
        # A local day can fall just outside the datetime range near either edge.
        probe = _boundary_probe(seconds)
        utc = _utc_datetime(probe)
        local = _to_local(utc, zone)
        offset = as_instant(local.replace(tzinfo=dt.timezone.utc)) - probe
        return (seconds + offset) // DAY_SECONDS + 1


def format_instant(seconds, zone):
    probe = seconds
    if not 0 <= seconds < CALENDAR_END:
        # A local time near either calendar boundary can sit outside the
        # corresponding UTC range. Get its offset just inside that range.
        if not -DAY_SECONDS < seconds < CALENDAR_END + DAY_SECONDS:
            raise OverflowError
        probe = _boundary_probe(seconds)
    local = _to_local(_utc_datetime(probe), zone)
    if probe != seconds:
        local += dt.timedelta(seconds=seconds - probe)
    # Some historical zones have sub-minute offsets. The output has minute precision.
    return local.isoformat(timespec="seconds")[:25]


def utc_key(minute):
    return _utc_datetime(minute * 60).isoformat(timespec="minutes") + "Z"


def _aligned(origin, first, step):
    return first + (origin - first) % step


def _month_index(day):
    return (day.year - 1) * 12 + day.month - 1


def _candidate_dates(rule, first, last):
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return

    lo, hi = first.toordinal(), last.toordinal()
    if rule.unit == "day":
        start = _aligned(rule.start.toordinal(), lo, rule.every)
        for ordinal in range(start, hi + 1, rule.every):
            yield dt.date.fromordinal(ordinal)
    elif rule.unit == "week":
        anchor = rule.start.toordinal() - rule.start.weekday()
        step = rule.every * 7
        start = _aligned(anchor, lo - first.weekday(), step)
        for monday in range(start, hi + 1, step):
            for weekday in rule.on:
                ordinal = monday + weekday
                if lo <= ordinal <= hi:
                    yield dt.date.fromordinal(ordinal)
    else:
        start = _aligned(_month_index(rule.start), _month_index(first), rule.every)
        cycle = GREGORIAN_CYCLE_MONTHS // gcd(rule.every, GREGORIAN_CYCLE_MONTHS)
        empty_months = 0
        for index in range(start, _month_index(last) + 1, rule.every):
            year, month = divmod(index, 12)
            year, month = year + 1, month + 1
            month_end = calendar.monthrange(year, month)[1]
            days = {month_end if item == "last" else item for item in rule.on
                    if item == "last" or item <= month_end}
            if not days:
                # Month lengths repeat every 400 years, including leap days.
                empty_months += 1
                if empty_months == cycle:
                    break
                continue
            empty_months = 0
            for day in sorted(days):
                candidate = dt.date(year, month, day)
                if first <= candidate <= last:
                    yield candidate


def _day_slots(ruledef, day):
    seen = set()
    for time in ruledef.rule.at:
        start = local_instant(dt.datetime.combine(day, time), ruledef.tz)
        if start not in seen:
            seen.add(start)
            yield time, start


def _calendar_slots(ruledef, first, last):
    for day in _candidate_dates(ruledef.rule, first, last):
        for time, start in _day_slots(ruledef, day):
            yield day, time, start


def _shifted_slots(ruledef, block, last):
    # Each source in the block shifts to the same date. An unshifted slot there
    # wins before counting or overrides, even if it won't be in the query.
    target = dt.date.fromordinal(min(block.stop, LAST_ORDINAL))
    beyond_calendar = block.stop > LAST_ORDINAL
    available = set(ruledef.rule.at)
    if not beyond_calendar:
        available.difference_update(time for _, time, _ in _calendar_slots(ruledef, target, target))
    if not available:
        return
    first = dt.date.fromordinal(block.start)
    for day, time, _ in _calendar_slots(ruledef, first, last):
        if time in available:
            start = local_instant(dt.datetime.combine(target, time), ruledef.tz)
            if beyond_calendar:
                start += DAY_SECONDS
            yield day, time, start
            available.remove(time)
            if not available:
                return


def _calendar_after_holidays(ruledef, holidays, first, last):
    if not holidays or ruledef.holiday == "keep":
        yield from _calendar_slots(ruledef, first, last)
        return
    rule = ruledef.rule
    cursor = max(first, rule.start).toordinal()
    last_ordinal = min(last, rule.until or last).toordinal()
    if cursor > last_ordinal:
        return
    for block in holidays.overlapping(cursor, last_ordinal):
        if cursor < block.start:
            yield from _calendar_slots(ruledef, dt.date.fromordinal(cursor), dt.date.fromordinal(block.start - 1))
        if ruledef.holiday == "shift":
            yield from _shifted_slots(ruledef, block, dt.date.fromordinal(min(block.stop - 1, last_ordinal)))
        cursor = block.stop
    if cursor <= last_ordinal:
        yield from _calendar_slots(ruledef, dt.date.fromordinal(cursor), last)


def calendar_candidates(ruledef, holidays, first, last):
    """Yield surviving keys and instants for an inclusive range of nominal dates."""
    rule = ruledef.rule
    remaining = rule.times
    scan_from = rule.start if remaining is not None else first
    for day, time, start in _calendar_after_holidays(ruledef, holidays, scan_from, last):
        if day >= first:
            yield dt.datetime.combine(day, time).isoformat(timespec="minutes"), start
        if remaining is not None:
            remaining -= 1
            if remaining == 0:
                return


def elapsed_candidates(ruledef, holidays, first, last):
    """Yield surviving UTC instants in [first, last) on the anchor's elapsed grid."""
    rule = ruledef.rule
    anchor = local_instant(rule.anchor, ruledef.tz)
    step = rule.every * ELAPSED_MINUTES[rule.unit] * 60
    skipping = False
    if ruledef.holiday == "skip" and holidays:
        scan_from = anchor if rule.times is not None else max(anchor, first)
        # A local date is at most one day from the date expressed in UTC.
        lo, hi = scan_from // DAY_SECONDS, (last - 1) // DAY_SECONDS + 2
        skipping = next(holidays.overlapping(lo, hi), None) is not None
    remaining = rule.times if skipping else None
    if rule.times is not None and not skipping:
        last = min(last, anchor + rule.times * step)
    until = rule.until.toordinal() if rule.until is not None else None
    if until is not None:
        last = min(last, until * DAY_SECONDS + DAY_SECONDS)
    if first >= last:
        return
    instant = anchor if remaining is not None else _aligned(anchor, max(anchor, first), step)
    if not skipping and until is None:
        yield from range(instant, last, step)
        return
    check_until_from = (until - 1) * DAY_SECONDS if until is not None else last
    while instant < last:
        if skipping or instant >= check_until_from:
            day = _local_ordinal(instant, ruledef.tz)
            block = holidays.containing(day) if skipping else None
            if block is not None:
                # Every possible offset puts the interior of a long block on
                # a holiday. Inspect its edges to allow for local dates moving backwards.
                exit_interior = (block.stop - 2) * DAY_SECONDS
                if block.start * DAY_SECONDS <= instant < exit_interior:
                    instant = _aligned(anchor, exit_interior, step)
                    continue
            if block is not None or (until is not None and day > until):
                instant += step
                continue
        if instant >= first:
            yield instant
        if remaining is not None:
            remaining -= 1
            if remaining == 0:
                return
        instant += step
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
import zoneinfo
from collections import defaultdict
from dataclasses import dataclass
from functools import lru_cache

from .errors import PlanError, RuleSyntaxError, describe_value
from .expand import as_instant, calendar_candidates, elapsed_candidates, local_instant, utc_key
from .holidays import Holidays, load_holidays
from .rules import DATE, LOCAL_DATETIME, Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: zoneinfo.ZoneInfo
    priority: int
    holiday: str


@dataclass
class Override:
    rule: RuleDef
    key: str
    start: int = None         # None for cancellations
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # (rule id, key) -> Override
    min_segment: int
    holidays: Holidays


@lru_cache(maxsize=1)
def _zone_names(_tzpath):
    # The search path is the cache key so a new path refreshes the names.
    return zoneinfo.available_timezones() - {"localtime"}


def _zone(name):
    if isinstance(name, str) and name in _zone_names(zoneinfo.TZPATH):
        # Exact membership keeps the spelling check independent of filesystem casing.
        try:
            return zoneinfo.ZoneInfo(name)
        except (ValueError, OSError, zoneinfo.ZoneInfoNotFoundError):
            pass
    raise PlanError(f"unknown timezone {describe_value(name)}")


def _load_rule(item, index, default_tz):
    if not isinstance(item, dict):
        raise PlanError(f"rule #{index} must be an object")
    rid = item.get("id")
    if not isinstance(rid, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
        raise PlanError(f"rule #{index} has an invalid id {describe_value(rid)}")
    try:
        rule = parse_rule(item.get("rule"))
        tz = _zone(item["timezone"]) if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError("priority must be an integer")
        holiday = item.get("holiday", "keep")
        if not isinstance(holiday, str) or holiday not in ("keep", "skip", "shift"):
            raise PlanError(f"invalid holiday policy {describe_value(holiday)}")
        if holiday == "shift" and rule.anchor is not None:
            raise PlanError("minute and hour rules cannot use holiday shift")
    except RuleSyntaxError as exc:
        raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text=exc.text) from exc
    except PlanError as exc:
        raise PlanError(f"rule {rid}: {exc}") from exc
    return RuleDef(index, rid, rule, tz, priority, holiday)


def _local_datetime(value):
    if not isinstance(value, str) or not re.fullmatch(LOCAL_DATETIME, value):
        raise ValueError
    return dt.datetime.fromisoformat(value)


def _load_override(item, rules):
    if not isinstance(item, dict):
        raise PlanError("override must be an object")
    rid = item.get("rule")
    if not isinstance(rid, str) or rid not in rules:
        raise PlanError(f"override for unknown rule {describe_value(rid)}")
    ruledef = rules[rid]
    key = item.get("key")
    if isinstance(key, str) and re.fullmatch(DATE, key) and len(ruledef.rule.at) == 1:
        key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
    try:
        if ruledef.rule.anchor is not None:
            if not isinstance(key, str) or not key.endswith("Z"):
                raise ValueError
            utc = _local_datetime(key[:-1]).replace(tzinfo=dt.timezone.utc)
            position = as_instant(utc)
        else:
            position = _local_datetime(key).date()
    except ValueError as exc:
        raise PlanError(f"rule {rid}: invalid override key {describe_value(key)}") from exc

    action = item.get("action")
    override = Override(ruledef, key)
    if action == "move":
        try:
            override.start = local_instant(_local_datetime(item.get("to")), ruledef.tz)
        except ValueError as exc:
            raise PlanError(f"rule {rid}: move override needs a valid 'to'") from exc
        override.minutes = ruledef.rule.minutes
        if "for" in item:
            override.minutes = parse_duration(item["for"])
            if override.minutes is None:
                raise PlanError(f"rule {rid}: invalid move duration {describe_value(item['for'])}")
    elif action != "cancel":
        raise PlanError(f"rule {rid}: unknown override action {describe_value(action)}")
    return override, position


def _keys_between(ruledef, holidays, first, last):
    if ruledef.rule.anchor is None:
        return (key for key, _ in calendar_candidates(ruledef, holidays, first, last))
    # An elapsed start can have seconds when the anchor's zone has a historical
    # sub-minute offset. Include the entire UTC minute named by the last key.
    return (utc_key(start // 60) for start in elapsed_candidates(ruledef, holidays, first, last + 60))


def _validate_keys(ruledef, holidays, positions_by_key):
    positions = set(positions_by_key.values())
    pending = set(positions_by_key)
    takes_scan = ruledef.rule.anchor is None or (holidays and ruledef.holiday == "skip")
    if ruledef.rule.times is not None and takes_scan:
        # Count from the rule's start only once, even for multiple overrides.
        for key in _keys_between(ruledef, holidays, min(positions), max(positions)):
            pending.discard(key)
            if not pending:
                return
    else:
        # Override keys can be far apart. Expand each position independently.
        for position in positions:
            pending.difference_update(_keys_between(ruledef, holidays, position, position))
    if pending:
        raise PlanError(f"rule {ruledef.id}: override key {min(pending)!r} has no occurrence")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    if not isinstance(raw.get("rules"), list):
        raise PlanError("rules must be a list")
    holidays = load_holidays(raw.get("holidays", []))
    rules = {}
    for index, item in enumerate(raw["rules"]):
        ruledef = _load_rule(item, index, default_tz)
        if ruledef.id in rules:
            raise PlanError(f"rule {ruledef.id}: duplicate id")
        rules[ruledef.id] = ruledef

    raw_overrides = raw.get("overrides", [])
    if not isinstance(raw_overrides, list):
        raise PlanError("overrides must be a list")
    overrides = {}
    override_positions = defaultdict(dict)
    for item in raw_overrides:
        override, position = _load_override(item, rules)
        rid, key = override.rule.id, override.key
        if (rid, key) in overrides:
            raise PlanError(f"rule {rid}: duplicate override for {key!r}")
        overrides[rid, key] = override
        override_positions[rid][key] = position
    for rid, positions_by_key in override_positions.items():
        _validate_keys(rules[rid], holidays, positions_by_key)

    min_segment = 0
    if "min_segment" in raw:
        min_segment = parse_duration(raw["min_segment"])
        if min_segment is None:
            raise PlanError(f"invalid min_segment {describe_value(raw['min_segment'])}")
    return Plan(list(rules.values()), overrides, min_segment, holidays)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re
from functools import lru_cache

from .errors import PlanError, describe_value
from .expand import (
    DAY_SECONDS, Occurrence, as_instant, calendar_candidates, date_at,
    elapsed_candidates, format_instant, utc_key,
)
from .plan import load_plan
from .rules import LOCAL_DATETIME

BOUND = re.compile(rf"{LOCAL_DATETIME}(?::[0-5][0-9])?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])")


def _parse_bound(text):
    if isinstance(text, str) and BOUND.fullmatch(text):
        try:
            return as_instant(dt.datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {describe_value(text)}")


def _window_candidates(ruledef, holidays, first, end, key_for_minute):
    if ruledef.rule.anchor is not None:
        try:
            for instant in elapsed_candidates(ruledef, holidays, first, end):
                yield key_for_minute(instant // 60), instant
        except OverflowError as exc:
            raise PlanError(f"rule {ruledef.id}: UTC key outside the four-digit calendar range") from exc
        return
    # A nominal wall time is less than a day from its UTC instant, even
    # when the pre-gap offset is used to interpret a nonexistent time.
    first_day = date_at(first - DAY_SECONDS)
    if ruledef.holiday == "shift":
        block = holidays.containing(first_day.toordinal() - 1)
        if block is not None:
            # The entire block may shift into the search range, even when its
            # source dates are far outside the query.
            first_day = dt.date.fromordinal(block.start)
    yield from calendar_candidates(ruledef, holidays, first_day, date_at(end + DAY_SECONDS))


def _collect(plan, start, end):
    found = []
    key_for_minute = lru_cache(maxsize=4096)(utc_key)
    for ruledef in plan.rules:
        length = ruledef.rule.minutes * 60
        for key, instant in _window_candidates(ruledef, plan.holidays, start - length + 1, end, key_for_minute):
            finish = instant + length
            if instant < end and finish > start and (ruledef.id, key) not in plan.overrides:
                found.append(Occurrence(ruledef, key, instant, finish))
    for override in plan.overrides.values():
        if override.start is not None:
            finish = override.start + override.minutes * 60
            if override.start < end and finish > start:
                found.append(Occurrence(override.rule, override.key, override.start, finish))
    return found


def _query(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if hi <= lo:
        raise PlanError("end must be after start")
    return plan, lo, hi, _collect(plan, lo, hi)


def _as_dict(occ, start, end, timestamp):
    try:
        start_text = timestamp(start, occ.rule.tz)
        end_text = timestamp(end, occ.rule.tz)
    except OverflowError as exc:
        raise PlanError(f"rule {occ.rule.id}: timestamp outside the four-digit calendar range") from exc
    return {
        "rule": occ.rule.id,
        "key": occ.key,
        "start": start_text,
        "end": end_text,
    }


def occurrences(plan, start, end):
    _, _, _, found = _query(plan, start, end)
    found.sort(key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    timestamp = lru_cache(maxsize=4096)(format_instant)
    return [_as_dict(occ, occ.start, occ.end, timestamp) for occ in found]


def _rank(occ):
    return -occ.rule.priority, occ.start, occ.rule.index, occ.key


def _segments(occurrences):
    """Yield maximal intervals of the highest-ranked active occurrence."""
    by_interval = {}
    for occ in occurrences:
        interval = (occ.start, occ.end)
        current = by_interval.get(interval)
        if current is None or _rank(occ) < _rank(current):
            by_interval[interval] = occ
    # The highest-ranked occurrence on an identical interval blocks all the
    # others on that interval and covers everything they would cover.
    starts = iter(sorted(by_interval.values(), key=lambda occ: occ.start))
    next_occ = next(starts, None)
    points = sorted({point for interval in by_interval for point in interval})
    active = []
    winner = segment_start = None
    for point in points:
        while next_occ is not None and next_occ.start == point:
            heapq.heappush(active, (_rank(next_occ), next_occ))
            next_occ = next(starts, None)
        while active and active[0][1].end <= point:
            heapq.heappop(active)
        current = active[0][1] if active else None
        if current is not winner:
            if winner is not None:
                yield winner, segment_start, point
            winner, segment_start = current, point


def agenda(plan, start, end):
    plan, lo, hi, found = _query(plan, start, end)
    minimum = plan.min_segment * 60
    rows = []
    timestamp = lru_cache(maxsize=4096)(format_instant)
    for occ, left, right in _segments(found):
        if (left != occ.start or right != occ.end) and right - left < minimum:
            continue
        left, right = max(left, lo), min(right, hi)
        if left < right:
            rows.append(_as_dict(occ, left, right, timestamp))
    return rows
